def flag_overdue(balances, limit):
    flagged = []
    for name in balances.keys():
        if balances[name] > limit:
            flagged.append(name)
    return flagged

if __name__ == "__main__":
    assert flag_overdue({"ana": 120, "bo": 30, "cy": 75}, 50) == ["ana", "cy"]
    assert flag_overdue({"ana": 10}, 50) == []
    print("behavior preserved")
